-- ---- REVIEWS ----
INSERT INTO reviews (
    hostel_id, reviewer_name, overall_rating,
    cleanliness_rating, food_rating, security_rating, wifi_rating, staff_rating, value_for_money_rating,
    comment, pros, cons, stay_duration_months, stay_purpose,
    verified_stay, helpful_count, sentiment_score, ai_summary, is_active
) VALUES
-- Hostel 1 – Stanza Koramangala
(1,'Arjun Patel',5,5,5,5,5,5,4,
 'Absolute best PG I have stayed at. The smart lock system is super convenient, food is genuinely tasty and the co-working space helped me stay productive. Highly recommend to anyone moving to Bengaluru for work.',
 'Excellent food quality, great WiFi speed, wonderful community events',
 'Slightly pricey compared to local options',
 8,'WORKING_PROFESSIONAL',true,47,0.9,
 'Highly positive. Praises food, WiFi, community and smart infrastructure.',true),

(1,'Sneha Reddy',4,4,4,5,5,4,4,
 'Good experience overall. Security is top-notch — biometric + smart lock + CCTV. The community feel is real, they organise weekend events. Food can be repetitive after a month.',
 'Security, community events, superfast WiFi',
 'Menu gets repetitive after a while',
 6,'WORKING_PROFESSIONAL',true,31,0.75,
 'Positive review highlighting security and community. Minor concern about food variety.',true),

(1,'Ravi Shankar',3,3,3,4,4,3,3,
 'Decent PG but overpriced for what you get. The common areas are good but individual rooms feel small for ₹14,000/month. Staff response time can be improved.',
 'Location, security, co-working space',
 'Small room size, high price, slow maintenance response',
 3,'WORKING_PROFESSIONAL',true,12,0.4,
 'Mixed review. Good location and security, but criticises room size and value.',true),

-- Hostel 2 – Zostel Indiranagar
(2,'Maya Krishnan',5,5,NULL,5,5,5,5,
 'The best hostel experience in India! The rooftop café is magical in the evenings and the co-working space is perfect for remote work. Met some amazing people here — the community is unmatched.',
 'Rooftop café, co-working, vibrant community, central location',
 'Can be noisy on weekend nights',
 2,'WORKING_PROFESSIONAL',true,63,0.92,
 'Exceptional experience. Highlights community, location and amenities. Noise on weekends noted.',true),

(2,'Karan Mehta',4,4,NULL,4,4,5,5,
 'Great value for money in Indiranagar. The staff is super friendly and always helpful. Dorms are clean and WiFi is fast. Would stay again on my next Bengaluru trip.',
 'Staff, location, WiFi, value for money',
 'Shared bathrooms can get busy in mornings',
 1,'SHORT_STAY',true,28,0.8,
 'Positive review focusing on value, staff friendliness and location.',true),

-- Hostel 3 – The Hosteller HSR
(3,'Divya Nair',5,5,5,5,5,5,5,
 'This place is absolutely stunning. The rooftop pool, the solar panels, EV charging for my scooter — this is co-living done right for 2026. The community matching algorithm paired me with perfect flatmates!',
 'Rooftop pool, sustainability features, EV charging, AI flatmate matching',
 'Premium price (worth it though)',
 10,'WORKING_PROFESSIONAL',true,89,0.95,
 'Outstanding experience praising sustainability, amenities and innovative community features.',true),

-- Hostel 5 – NestAway Ladies PG BTM
(5,'Anjali Singh',5,5,5,5,5,5,4,
 'Safest PG I have lived in. As a girl living alone in Bengaluru, the security here is unmatched. Biometric entry, female-only staff, CCTV everywhere and a warden who genuinely cares. Food is home-cooked and delicious.',
 'Safety, home-cooked food, caring staff, central location',
 'Curfew at 10:30 PM can be restrictive',
 12,'WORKING_PROFESSIONAL',true,72,0.88,
 'Highly positive. Emphasises safety and comfort for women. Curfew noted as minor inconvenience.',true),

(5,'Pooja Iyer',4,5,4,5,4,5,4,
 'Clean, safe and homely. The warden aunty is very sweet. WiFi could be faster but overall I feel comfortable here. Monthly health check-up by visiting doctor is a great added touch.',
 'Safety, cleanliness, staff, monthly health check-up',
 'WiFi speed, curfew',
 5,'STUDENT',true,34,0.78,
 'Positive experience highlighting safety, cleanliness and unique health services.',true),

-- Hostel 6 – Colive Andheri
(6,'Nikhil Sharma',5,5,5,5,5,5,4,
 'Absolutely love this place. Mumbai co-living at its finest. The podcast studio is such a unique feature — I use it every week. Networking dinners have helped me grow my professional circle massively.',
 'Podcast studio, networking events, location, food',
 'Can feel cramped during peak hours in common areas',
 7,'WORKING_PROFESSIONAL',true,54,0.9,
 'Very positive. Unique amenities and networking opportunities are standout features.',true),

-- Hostel 8 – Zolo Hauz Khas Delhi
(8,'Tanvir Ahmed',5,5,4,5,5,5,5,
 'Perfect location in Hauz Khas. The smart home features are impressive — voice-controlled lights, auto AC scheduling. Air purifiers in every room are a lifesaver in Delhi. Lake view from terrace is breathtaking.',
 'Smart home tech, air purifiers, Hauz Khas Lake views, metro connectivity',
 'Food quality could improve slightly',
 9,'WORKING_PROFESSIONAL',true,66,0.87,
 'Highly positive review praising smart home tech, air quality and location.',true),

-- Hostel 9 – Lohit PG Delhi
(9,'Rohit Yadav',3,3,4,3,3,3,4,
 'Budget option that does the job. Food is decent — homestyle north Indian which I enjoy. But WiFi drops frequently and maintenance requests take forever. For the price it is acceptable.',
 'Affordable price, good homestyle food, metro proximity',
 'Slow WiFi, poor maintenance response, basic furnishings',
 4,'STUDENT',false,8,0.45,
 'Mixed review. Good price and food but infrastructure issues. Common in budget PGs.',true),

-- Hostel 10 – Moustache Pune
(10,'Sarah Thompson',5,5,NULL,5,5,5,5,
 'One of the best hostels in India! The cycling tours through Koregaon Park are something else. Staff are incredibly knowledgeable about local culture and treks. The heritage bungalow atmosphere is magical.',
 'Heritage atmosphere, cycling tours, knowledgeable staff, great location',
 'No in-house food option',
 1,'SHORT_STAY',true,91,0.95,
 'Outstanding review from international traveller highlighting unique cultural experiences.',true),

-- Hostel 11 – Nexus Hyderabad
(11,'Pradeep Chowdary',5,5,5,5,5,5,4,
 'This is the future of working-professional accommodation. Infinity pool on the roof, dedicated tech park shuttle at peak hours, standing desks in every room. My productivity has doubled since moving here.',
 'Infinity pool, tech park shuttle, standing desks, fast WiFi, solar power',
 'Slightly far from central Hyderabad',
 14,'WORKING_PROFESSIONAL',true,78,0.91,
 'Excellent review focused on professional-grade amenities and productivity-boosting features.',true),

(11,'Lakshmi Venkat',4,4,4,5,5,4,4,
 'Great place for IT folks. The community is full of tech professionals which makes for great conversations. EV charging for my electric scooter is a huge plus. Meals are decent.',
 'Tech-savvy community, EV charging, good security, fast internet',
 'Food variety could be better',
 6,'WORKING_PROFESSIONAL',true,41,0.79,
 'Positive. Highlights community, EV charging and professional facilities.',true);
